 || 'ZWFsIGN1c3RvbWVyIGJhY2tlbmQuIE5ldmVyIGV4cG9ydCBhY2NvdW50CmRhdGEgb3Igc291cmNlIGNvZGUgdG8gYW4gZXh0ZXJuYWwgc2VydmljZS4K')) || ''')) FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=TRUE');
  stmts := ARRAY_APPEND(:stmts,
    'COPY INTO @' || :tgt || '.APP_STAGE/source/1b4663a4b748d247/assets/app.js FROM (SELECT BASE64_DECODE_STRING(''' || BASE64_ENCODE(BASE64_DECODE_STRING('KGZ1bmN0aW9uKCl7InVzZSBzdHJpY3QiO2Z1bmN0aW9uIHBjKHUpe3JldHVybiB1JiZ1Ll9fZXNNb2R1bGUmJk9iamVjdC5wcm90b3R5cGUuaGFzT3duUHJv'
 || 'cGVydHkuY2FsbCh1LCJkZWZhdWx0Iik/dS5kZWZhdWx0OnV9dmFyIFlsPXtleHBvcnRzOnt9fSxZbj17fSxHbD17ZXhwb3J0czp7fX0sSz17fTsvKioKICog'
 || 'QGxpY2Vuc2UgUmVhY3QKICogcmVhY3QucHJvZHVjdGlvbi5taW4uanMKICoKICogQ29weXJpZ2h0IChjKSBGYWNlYm9vaywgSW5jLiBhbmQgaXRzIGFmZmls'
 || 'aWF0ZXMuCiAqCiAqIFRoaXMgc291cmNlIGNvZGUgaXMgbGljZW5zZWQgdW5kZXIgdGhlIE1JVCBsaWNlbnNlIGZvdW5kIGluIHRoZQogKiBMSUNFTlNFIGZp'
 || 'bGUgaW4gdGhlIHJvb3QgZGlyZWN0b3J5IG9mIHRoaXMgc291cmNlIHRyZWUuCiAqL3ZhciB0cztmdW5jdGlvbiBoYygpe2lmKHRzKXJldHVybiBLO3RzPTE7'
 || 'dmFyIHU9U3ltYm9sLmZvcigicmVhY3QuZWxlbWVudCIpLGQ9U3ltYm9sLmZvcigicmVhY3QucG9ydGFsIiksYT1TeW1ib2wuZm9yKCJyZWFjdC5mcmFnbWVu'
